{'code': "from qgis.utils import plugins
mmqgis = plugins.get('mmqgis')
menu = mmqgis.mmqgis_menu
found = []
for a in menu.actions():
    m = a.menu()
    if m is not None:
        for sa in m.actions():
            if 'join' in (sa.text() or '').lower() or 'csv' in (sa.text() or '').lower():
                found.append({
                    'submenu': (a.text() or '').replace('&',''),
                    'action_text': sa.text(),
                    'enabled': sa.isEnabled(),
                    'visible': sa.isVisible(),
                })
    else:
        if 'join' in (a.text() or '').lower() or 'csv' in (a.text() or '').lower():
            found.append({'submenu': None, 'action_text': a.text(), 'enabled': a.isEnabled(), 'visible': a.isVisible()})
result = found"}
